// Abstract class SortAlgorithm
abstract class SortAlgorithm {
    abstract int compare(Object a, Object b);
    abstract void swap(Object[] array, int i, int j);

    void sort(Object[] array) {
        // Template method
        for (int i = 0; i < array.length - 1; i++) {
            int index = findSmallestUnsortedIndex(array, i);
            swap(array, i, index);
        }
    }

    // Helper method to be overridden in subclasses
    protected abstract int findSmallestUnsortedIndex(Object[] array, int endIndex) {
        // Default implementation that throws an exception
        throw new UnsupportedOperationException("Subclasses must implement this method.");
    }
}

// Concrete subclass BubbleSort
class BubbleSort extends SortAlgorithm {
    @Override
    int compare(Object a, Object b) {
        return ((Comparable) a).compareTo((Comparable) b);
    }

    @Override
    void swap(Object[] array, int i, int j) {
        Object temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    @Override
    protected int findSmallestUnsortedIndex(Object[] array, int endIndex) {
        for (int i = 0; i < endIndex; i++) {
            if (compare(array[i], array[endIndex]) < 0) {
                return i;
            }
        }
        return endIndex;
    }
}

// Concrete subclass SelectionSort
class SelectionSort extends SortAlgorithm {
    @Override
    int compare(Object a, Object b) {
        return ((Comparable) a).compareTo((Comparable) b);
    }

    @Override
    void swap(Object[] array, int i, int j) {
        Object temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    @Override
    protected int findSmallestUnsortedIndex(Object[] array, int endIndex) {
        int minIndex = endIndex - 1;
        for (int i = 0; i < endIndex; i++) {
            if (compare(array[i], array[minIndex]) < 0) {
                minIndex = i;
            }
        }
        return minIndex;
    }
}

// Testing
public class Main {
    public static void main(String[] args) {
        SortAlgorithm bubbleSort = new BubbleSort();
        SortAlgorithm selectionSort = new SelectionSort();

        Integer[] array = {5, 2, 8, 1, 4};
        bubbleSort.sort(array);
        System.out.println("Array after Bubble Sort: " + Arrays.toString(array));

        selectionSort.sort(array);
        System.out.println("Array after Selection Sort: " + Arrays.toString(array));
    }
}
